\section{Spoectroscopy Areas}

\begin{itemize}
\item \PMlinkexternal{Atomic spectroscopy}{} 
\item \PMlinkexternal{Emission spectroscopy}{http://en.wikipedia.org/wiki/Emission_spectroscopy} 
\item \PMlinkexternal{Electron spectroscopy}{}, including Auger spectroscopy 
\item \PMlinkexternal{Electron spin resonance}{} 
\item \PMlinkexternal{Fourier transform spectroscopy and imaging}{}  
\item \PMlinkexternal{Fluorescence spectroscopy}{}, including Fluorescence Correlation Spectroscopy ({\em FCS}) and Fluorescence Cross-Correlation Spectroscopy ({\em FCCS})
\item Gamma spectroscopy 
\item \PMlinkexternal{Infrared spectroscopy (IR)}{}
\item Laser induced breakdown spectroscopy
\item Mass spectrometry (MS)
\item \PMlinkexternal{Microspectroscopy}{}: including fluorescence/FLIM, IR and \PMlinkexternal{NIR microspectroscopy}{}
\item $M\ddot{o}ssbauer$ spectroscopy 
\item \PMlinkexternal{Near Infrared spectroscopy (NIR)}{}
\item Hyperspectral, or Chemical NIR (IR), Imaging
\item Nuclear magnetic resonance spectroscopy, including FT-NMR, 2D-FT NMR
and NMR Imaging
\item Positron annihilation spectroscopy and imaging (PET scanning)
\item Raman spectroscopy 
\item Resonance enhanced multiphoton ionization 
\item Rotational Microwave spectroscopy 
\item Terahertz spectroscopy 
\item Ultraviolet-visible spectroscopy 
\item Vibrational spectroscopy 
\item X-ray spectroscopy
\end{itemize}
